This version keeps the two searches separate. DFS uses an explicit stack instead of recursion, which avoids growing the call stack on a long chain. BFS uses a normal queue. A node is marked when it is added, so the same node is not pushed more than once.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
  public:
    vector<int> dfsOfGraph(int V, vector<vector<int>> edges) {
        vector<int> order;
        if (V == 0) return order;

        vector<int> visited(V, 0);
        stack<int> pending;
        pending.push(0);
        visited[0] = 1;

        while (!pending.empty()) {
            int node = pending.top();
            pending.pop();
            order.push_back(node);

            for (int i = static_cast<int>(edges[node].size()) - 1; i >= 0; --i) {
                int next = edges[node][i];
                if (!visited[next]) {
                    visited[next] = 1;
                    pending.push(next);
                }
            }
        }

        return order;
    }

    vector<int> bfsOfGraph(int V, vector<vector<int>> edges) {
        vector<int> order;
        if (V == 0) return order;

        vector<int> visited(V, 0);
        queue<int> pending;
        pending.push(0);
        visited[0] = 1;

        while (!pending.empty()) {
            int node = pending.front();
            pending.pop();
            order.push_back(node);

            for (int next : edges[node]) {
                if (!visited[next]) {
                    visited[next] = 1;
                    pending.push(next);
                }
            }
        }

        return order;
    }
};
```

The reverse loop in DFS makes the first neighbor appear on top of the stack first. That keeps the visit order close to the order in the adjacency list.

Time: `O(V + E)`. Space: `O(V)`. The input adjacency list is not changed.

The graph is already given as an adjacency list, so there is no need to build another graph. DFS goes as deep as possible through recursion, while BFS visits nearby vertices with a queue. Both start from vertex 0 and mark a vertex before exploring it.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    void dfsHelper(int node, vector<vector<int>>& edges, vector<int>& visited,
                   vector<int>& order) {
        visited[node] = 1;
        order.push_back(node);

        for (int next : edges[node]) {
            if (!visited[next]) {
                dfsHelper(next, edges, visited, order);
            }
        }
    }

  public:
    vector<int> dfsOfGraph(int V, vector<vector<int>> edges) {
        vector<int> order;
        if (V == 0) return order;

        vector<int> visited(V, 0);
        dfsHelper(0, edges, visited, order);
        return order;
    }

    vector<int> bfsOfGraph(int V, vector<vector<int>> edges) {
        vector<int> order;
        if (V == 0) return order;

        vector<int> visited(V, 0);
        queue<int> pending;
        pending.push(0);
        visited[0] = 1;

        while (!pending.empty()) {
            int node = pending.front();
            pending.pop();
            order.push_back(node);

            for (int next : edges[node]) {
                if (!visited[next]) {
                    visited[next] = 1;
                    pending.push(next);
                }
            }
        }

        return order;
    }
};
```

For a graph like `0 -> [1, 2]`, DFS takes one neighbor fully before trying the other. BFS puts both neighbors in the queue first.

Time complexity: `O(V + E)` for either traversal. Space complexity: `O(V)` for the visited array and traversal storage, not counting the input graph.

The recursive method is short because the call stack stores the next DFS steps for us. For BFS, vertices are processed in the same order in which they enter the queue. The `V == 0` check also keeps the starting access safe.

```java
import java.util.*;

class Solution {
    private void visitDepthFirst(int node, List<List<Integer>> edges,
                                 boolean[] visited, List<Integer> order) {
        visited[node] = true;
        order.add(node);

        for (int next : edges.get(node)) {
            if (!visited[next]) {
                visitDepthFirst(next, edges, visited, order);
            }
        }
    }

    public List<Integer> dfsOfGraph(int V, List<List<Integer>> edges) {
        List<Integer> order = new ArrayList<>();
        if (V == 0) return order;

        boolean[] visited = new boolean[V];
        visitDepthFirst(0, edges, visited, order);
        return order;
    }

    public List<Integer> bfsOfGraph(int V, List<List<Integer>> edges) {
        List<Integer> order = new ArrayList<>();
        if (V == 0) return order;

        boolean[] visited = new boolean[V];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        visited[0] = true;

        while (!queue.isEmpty()) {
            int node = queue.removeFirst();
            order.add(node);

            for (int next : edges.get(node)) {
                if (!visited[next]) {
                    visited[next] = true;
                    queue.addLast(next);
                }
            }
        }

        return order;
    }
}
```

Dry run for `0 -> [1, 2]` and `1 -> [3]`: DFS can produce `[0, 1, 3, 2]`. BFS produces `[0, 1, 2, 3]` because it finishes the first layer before moving deeper.

Both methods take `O(V + E)` time. The visited array, queue, or recursion uses `O(V)` extra space.

Here DFS is written with a slice used as a stack. BFS uses another slice as a queue with a moving index, so elements are not repeatedly removed from the front. The visited slice is updated when a vertex is added to either structure.

```go
package main

func dfsOfGraph(V int, edges [][]int) []int {
	order := make([]int, 0)
	if V == 0 {
		return order
	}

	visited := make([]bool, V)
	stack := []int{0}
	visited[0] = true

	for len(stack) > 0 {
		last := len(stack) - 1
		node := stack[last]
		stack = stack[:last]
		order = append(order, node)

		for i := len(edges[node]) - 1; i >= 0; i-- {
			next := edges[node][i]
			if !visited[next] {
				visited[next] = true
				stack = append(stack, next)
			}
		}
	}

	return order
}

func bfsOfGraph(V int, edges [][]int) []int {
	order := make([]int, 0)
	if V == 0 {
		return order
	}

	visited := make([]bool, V)
	queue := []int{0}
	visited[0] = true

	for head := 0; head < len(queue); head++ {
		node := queue[head]
		order = append(order, node)

		for _, next := range edges[node] {
			if !visited[next] {
				visited[next] = true
				queue = append(queue, next)
			}
		}
	}

	return order
}
```

The reverse neighbor loop in DFS is only for keeping the usual adjacency-list order when using a stack. It is not needed for correctness if any valid DFS order is accepted.

Time complexity: `O(V + E)` for each function. Space complexity: `O(V)` for visited and the stack or queue. The functions do not modify `edges`.

The adjacency lists are used directly. DFS calls itself for each unvisited neighbor. BFS uses `deque`, since removing from the front of a normal Python list would be slow.

```python
from collections import deque

class Solution:
    def dfsOfGraph(self, V, edges):
        if V == 0:
            return []

        visited = [False] * V
        order = []

        def visit(node):
            visited[node] = True
            order.append(node)

            for next_node in edges[node]:
                if not visited[next_node]:
                    visit(next_node)

        visit(0)
        return order

    def bfsOfGraph(self, V, edges):
        if V == 0:
            return []

        visited = [False] * V
        order = []
        queue = deque([0])
        visited[0] = True

        while queue:
            node = queue.popleft()
            order.append(node)

            for next_node in edges[node]:
                if not visited[next_node]:
                    visited[next_node] = True
                    queue.append(next_node)

        return order
```

An isolated vertex is simply not added unless it can be reached from vertex 0, which matches a traversal that starts at 0. If `V` is zero, both methods return an empty list.

Dry run: with edges `[[1], [0, 2], [1]]`, DFS returns `[0, 1, 2]`, and BFS returns the same because the graph is just a chain.

Time complexity is `O(V + E)`. Space complexity is `O(V)`, excluding the given adjacency lists.
